+<style>
+/* 値は `index.html` の写し。共有ファイルにしない理由は `check-pr-explain-template.py` の docstring。 */
+:root {
+  --bg: #F6F5F1;
+  --panel: #FBFAF7;
+  --surface: #FFFFFF;
+  --hover: #F4F2ED;
+  --line: #E2DFD8;
