+<body>
+<header class="top"><span class="repo">design-composer</span><span class="hint">読み込み中…</span></header>
+<main class="list" id="list"></main>
+<script>
+(() => {
+  "use strict";
+
+  /** 一覧(`list.json`)の読み方。DOM に触らない。 */
+  const ListPage = (() => {
+    const ListVersion = 1;
+    const isRecord = (value) => typeof value === "object" && value !== null && !Array.isArray(value);
+    const isPrNumber = (value) => Number.isInteger(value) && value > 0;
+    const isTitle = (value) => typeof value === "string" || value === null;
+    const missing = (reason) => ({ kind: "missing", reason });
+
+    const parsedJson = (text) => {
+      try {
+        return { isParsed: true, value: JSON.parse(text) };
+      } catch (error) {
+        return { isParsed: false, detail: error.message };
+      }
+    };
+
+    /**
+     * 行の並びのうち、最初に形の違う行のキー。
+     * @returns 行がオブジェクトでなければ `pages`、番号が正の整数でなければ `pr`、題が文字列でも null でもなければ `title`。どの行も合っていれば null
+     */
+    const rowProblemOf = (pages) => {
+      for (const row of pages) {
+        if (!isRecord(row)) return "pages";
+        if (!isPrNumber(row.pr)) return "pr";
+        if (!isTitle(row.title)) return "title";
+      }
+      return null;
+    };
+
+    return Object.freeze({
+      /**
+       * 読み込んだ一覧を、行の並び・0 件・読めない理由のどれかにする。行は並べ替えない(並びは置く側が決める)。
+       * @param source `{kind: "text", text}`(読めた中身)/ `{kind: "absent"}`(置かれていない)/ `{kind: "failed", detail}`(読み込みの失敗)
+       * @returns `{kind: "listed", rows}`(行は番号・題・リンク先)/ `{kind: "empty"}` / `{kind: "missing", reason}`(reason の kind は
+       *   absent・unreadable・shape(形の違うキー。トップなら null)・version)
+       */
+      readingOf: (source) => {
+        if (source.kind === "absent") return missing({ kind: "absent" });
+        if (source.kind === "failed") return missing({ kind: "unreadable", detail: source.detail });
+        const json = parsedJson(source.text);
+        if (!json.isParsed) return missing({ kind: "unreadable", detail: json.detail });
+        const list = json.value;
+        if (!isRecord(list)) return missing({ kind: "shape", key: null });
+        if (list.version !== ListVersion) return missing({ kind: "version", actual: list.version ?? null });
+        if (!Array.isArray(list.pages)) return missing({ kind: "shape", key: "pages" });
+        const problem = rowProblemOf(list.pages);
+        if (problem !== null) return missing({ kind: "shape", key: problem });
+        if (list.pages.length === 0) return { kind: "empty" };
+        return { kind: "listed", rows: list.pages.map((row) => ({ pr: row.pr, title: row.title, href: `pr-${row.pr}/` })) };
+      },
+    });
+  })();
+
+  /** DOM に触らない部分(核)。判定表が node の vm で評価して叩く。 */
+  const core = Object.freeze({ ListPage });
+  if (typeof document === "undefined") {
+    globalThis.prExplainListCore = core;
+    return;
+  }
+
+  /**
+   * 要素を作る。文字は textContent で入れる。
+   * @param attributes `class` / `href` など、そのまま setAttribute する属性と、中の文字(`text`)
+   */
+  const el = (tag, attributes = {}, children = []) => {
+    const node = document.createElement(tag);
+    for (const [name, value] of Object.entries(attributes)) {
+      if (name === "text") node.textContent = value;
+      else node.setAttribute(name, value);
+    }
+    node.append(...children);
+    return node;
+  };
+
+  /** 一覧を読めない理由の 1 文。 */
+  const missingTextOf = (reason) => {
+    switch (reason.kind) {
+      case "absent":
+        return "list.json がまだ置かれていません。Actions が次に一覧を作り直すと出ます。";
+      case "unreadable":
+        return `list.json を読めませんでした(${reason.detail})。`;
+      case "shape":
+        return `list.json の ${reason.key ?? "トップ"} の形が想定と違います。`;
+      case "version":
+        return `list.json の version が ${JSON.stringify(reason.actual)} で、このページが読めるのは 1 です。`;
+    }
+  };
+
+  const rowOf = (row) => {
+    const title = row.title === null ? el("span", { class: "title untitled", text: "題を取得できませんでした" }) : el("span", { class: "title", text: row.title });
+    return el("li", {}, [el("a", { href: row.href }, [el("span", { class: "number mono", text: `#${row.pr}` }), title])]);
+  };
+
+  /** 読んだ一覧の本文。 */
+  const contentOf = (reading) => {
+    switch (reading.kind) {
+      case "listed":
+        return [el("p", { class: "count", text: `${reading.rows.length} 件(番号の大きい順)` }), el("ul", { class: "pages" }, reading.rows.map(rowOf))];
+      case "empty":
+        return [el("div", { class: "note" }, [el("p", { text: "残っている解説ページはありません" })])];
+      case "missing":
+        return [el("div", { class: "note", role: "status" }, [el("h2", { text: "一覧を読めません" }), el("p", { text: missingTextOf(reading.reason) })])];
+    }
+  };
+
+  const listRequest = fetch(`list.json?t=${Date.now()}`, { cache: "no-store" })
+    .then((response) => {
+      if (response.status === 404) return { kind: "absent" };
+      if (!response.ok) return { kind: "failed", detail: `HTTP ${response.status}` };
+      return response.text().then((text) => ({ kind: "text", text }));
+    })
+    .catch((error) => ({ kind: "failed", detail: error.message }));
+
+  listRequest.then((source) => {
+    document.querySelector(".top .hint").remove();
+    document.getElementById("list").replaceChildren(el("h1", { text: "PR 解説の一覧" }), ...contentOf(ListPage.readingOf(source)));
+  });
+})();
+</script>
+</body>
+</html>

